Here is the recipe JSON:
{
  "recipe_name": "Homemade Pizza",
  "ingredients": [
    "2 cups of warm water",
    "2 teaspoons of sugar",
    "1 tablespoon of active dry yeast",
    "3 1/2 cups of all-purpose flour",
    "1 teaspoon of salt",
    "2 tablespoons of olive oil",
    "1/2 cup of pizza sauce",
    "1 cup of shredded mozzarella cheese",
    "Toppings of your choice (e.g. pepperoni, bell peppers, onions, mushrooms)"
  ],
  "steps": [
    {
      "step_number": 1,
      "instruction": "In a large mixing bowl, combine warm water, sugar, and yeast. Let it sit for 5-10 minutes until the yeast is activated.",
      "time": "10 minutes",
      "tip": "Make sure the water is not too hot, as it can kill the yeast."
    },
    {
      "step_number": 2,
      "instruction": "Add flour, salt, and olive oil to the bowl. Mix until a dough forms.",
      "time": "5 minutes",
      "tip": "Use a stand mixer with a dough hook attachment for easier mixing."
    },
    {
      "step_number": 3,
      "instruction": "Knead the dough on a floured surface for 5-10 minutes until it becomes smooth and elastic.",
      "time": "10 minutes",
      "tip": "Use a little bit of flour to prevent the dough from sticking to the surface."
    },
    {
      "step_number": 4,
      "instruction": "Place the dough in a greased bowl, cover it with a damp cloth, and let it rise in a warm place for 1-2 hours until it has doubled in size.",
      "time": "1-2 hours",
      "tip": "Make sure the place is warm and draft-free for the dough to rise properly."
    },
    {
      "step_number": 5,
      "instruction": "Preheat the oven to 425\u00b0F (220\u00b0C). Punch down the dough and shape it into a circle or rectangle.",
      "time": "5 minutes",
      "tip": "Use a pizza peel or a baking sheet to shape the dough."
    },
    {
      "step_number": 6,
      "instruction": "Spread the pizza sauce over the dough, leaving a small border around the edges.",
      "time": "2 minutes",
      "tip": "Use a spoon or a brush to spread the sauce evenly."
    },
    {
      "step_number": 7,
      "instruction": "Add shredded mozzarella cheese and your desired toppings.",
      "time": "2 minutes",
      "tip": "Don't overload the pizza with too many toppings, as it can make the crust soggy."
    },
    {
      "step_number": 8,
      "instruction": "Bake the pizza in the preheated oven for 15-20 minutes until the crust is golden brown and the cheese is melted and bubbly.",
      "time": "15-20 minutes",
      "tip": "Keep an eye on the pizza while it's baking, as the cooking time may vary depending on the toppings and the oven."
    }
  ]
}
